Amós 9 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"Onde o profeta viu o Senhor em pé?","o":["Sobre o altar","No cume do Carmelo","À porta da cidade","Junto ao rio do Egito"],"c":0,"v":1,"e":"No versículo 1 o profeta diz: \"Vi o Senhor, que estava em pé sobre o altar\"."},
{"t":"multipla","p":"Se se escondessem nas profundezas do mar, o que o Senhor faria?","o":["Mandaria uma tempestade","Secaria o mar","Daria ordem à serpente para mordê-los","Enviaria pescadores para buscá-los"],"c":2,"v":3,"e":"No versículo 3 o Senhor diz que daria ordem à serpente, e ela os morderia."},
{"t":"multipla","p":"De onde o Senhor diz que fez subir os filisteus?","o":["De Quir","De Caftor","Do Egito","De Edom"],"c":1,"v":7,"e":"No versículo 7 o Senhor lembra que tirou Israel do Egito, os filisteus de Caftor e os siros de Quir."},
{"t":"multipla","p":"Com que imagem o Senhor descreve como sacudirá a casa de Israel entre as nações?","o":["Como o vento espalha a palha","Como o pastor separa as ovelhas","Como se sacode o grão no crivo","Como o lavrador ara a terra"],"c":2,"v":9,"e":"No versículo 9 o Senhor diz que sacudirá Israel como se sacode o grão no crivo, sem que caia na terra um só grão."},
{"t":"multipla","p":"O que o Senhor promete levantar \"naquele dia\"?","o":["O altar de Betel","Os muros de Samaria","O templo de Salomão","A tenda caída de Davi"],"c":3,"v":11,"e":"No versículo 11 o Senhor promete levantar a tenda caída de Davi, fechar suas brechas e reerguer suas ruínas."},
{"t":"cv","p":"Os pecadores do povo diziam: \"O mal não nos alcançará, nem nos encontrará.\"","c":true,"v":10,"e":"O versículo 10 diz que morrerão à espada os pecadores que falam assim."},
{"t":"cv","p":"O Senhor anuncia dias em que os montes vão secar e as colinas ficarão estéreis.","c":false,"v":13,"e":"No versículo 13 o Senhor diz que os montes transbordarão de mosto e todas as colinas se derreterão."},
{"t":"cv","p":"O Senhor promete plantar o povo na sua terra, e ele não será mais arrancado dela.","c":true,"v":15,"e":"No versículo 15 o Senhor diz: \"E eu os plantarei na sua terra, e não serão mais arrancados dela\"."}
]}

Amós 6 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Em que monte estão os que se sentem seguros?","o":["Monte de Samaria","Monte Carmelo","Monte Sinai","Monte das Oliveiras"],"c":0,"v":1,"e":"No início do capítulo, o ai é contra os que estão à vontade em Sião e os que se sentem seguros no monte de Samaria."},
 {"t":"multipla","p":"Que lugares o profeta manda visitar para comparar com Israel?","o":["Nínive, Babilônia e Damasco","Calné, Hamate e Gate","Jericó, Betel e Gilgal","Tiro, Sidom e Gaza"],"c":1,"v":2,"e":"O versículo 2 manda ir a Calné, seguir até a grande Hamate e descer até Gate dos filisteus."},
 {"t":"multipla","p":"Em que tipo de cama repousam os que vivem no luxo?","o":["Camas de cedro","Camas de ouro","Camas de marfim","Camas de prata"],"c":2,"v":4,"e":"O versículo 4 diz que eles repousam em camas de marfim e se deliciam com cordeiros e bezerros."},
 {"t":"multipla","p":"Com o que esses que bebem vinho em taças não se afligem?","o":["Com a seca na terra","Com a ruína de José","Com a guerra dos filisteus","Com a pobreza de Judá"],"c":1,"v":6,"e":"O versículo 6 diz que eles se ungem com o melhor óleo, mas não se afligem com a ruína de José."},
 {"t":"multipla","p":"O que o SENHOR jura que abomina?","o":["Os sacrifícios de Israel","Os ídolos de Samaria","A soberba de Jacó","As canções de Sião"],"c":2,"v":8,"e":"No versículo 8, o SENHOR jura por si mesmo que abomina a soberba de Jacó e odeia os seus castelos."},
 {"t":"cv","p":"Quem leva os cadáveres para fora da casa é orientado a invocar o nome do SENHOR.","c":false,"v":10,"e":"No versículo 10, ele diz o contrário: \"Cala-te, não menciones o nome do SENHOR\"."},
 {"t":"cv","p":"O povo transformou o juízo em veneno e o fruto da justiça em alosna.","c":true,"v":12,"e":"Depois de perguntar se cavalos correm sobre a rocha, o versículo 12 acusa o povo de ter feito exatamente isso."},
 {"t":"cv","p":"O Senhor diz que levantará uma nação que oprimirá Israel desde a entrada de Hamate até o ribeiro da Arabá.","c":true,"v":14,"e":"O último versículo do capítulo anuncia essa nação e os limites da opressão, de Hamate até o ribeiro da Arabá."}
]}

Amós 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o SENHOR, quantos conservará a cidade que possui mil?","o":["Dez","Cem","Quinhentos","Nenhum"],"c":1,"v":3,"e":"O versículo 3 diz que a cidade que possui mil conservará cem."},
 {"t":"multipla","p":"Quais lugares o povo não deveria buscar?","o":["Jerusalém, Siló e Hebrom","Samaria, Dã e Jericó","Betel, Gilgal e Berseba","Sião, Belém e Gade"],"c":2,"v":5,"e":"O versículo 5 manda não buscar Betel, não ir a Gilgal e não passar por Berseba."},
