 {"t":"multipla","p":"O que o povo deveria estabelecer na porta?","o":["Um altar","O juízo","Uma torre de vigia","Um mercado"],"c":1,"v":15,"e":"O versículo 15 diz: estabeleçam o juízo na porta."},
 {"t":"cv","p":"O Dia do Senhor é comparado a quem foge de um leão e se depara com um urso.","c":true,"v":19,"e":"O versículo 19 traz essa comparação com o leão e o urso."},
 {"t":"cv","p":"Deus diz que se agradará dos holocaustos e das ofertas de grãos do povo.","c":false,"v":22,"e":"O versículo 22 diz que, mesmo que lhe apresentem holocaustos e ofertas de grãos, Deus não se agradará delas."},
 {"t":"cv","p":"O SENHOR anuncia que desterrará o povo para o Egito.","c":false,"v":27,"e":"O versículo 27 diz que o SENHOR os desterrará além de Damasco."}
]}

Amós 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o capítulo, o que Moabe fez com os ossos do rei de Edom?","o":["Queimou-os, reduzindo-os a cal","Enterrou-os no deserto","Jogou-os no rio","Levou-os para Queriote"],"c":0,"v":1,"e":"O versículo 1 diz que Moabe queimou os ossos do rei de Edom, reduzindo-os a cal."},
