]}

Amós 7 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Na primeira visão, o que o Senhor Deus estava formando?","o":["Gafanhotos","Rãs","Granizo","Nuvens de poeira"],"c":0,"v":1,"e":"No versículo 1, Amós vê o Senhor formando gafanhotos quando a erva serôdia começava a crescer."},
 {"t":"multipla","p":"Na segunda visão, o que o Senhor Deus chamava para exercer a sua justiça?","o":["Um dilúvio","O fogo","Uma seca","Um exército"],"c":1,"v":4,"e":"No versículo 4, o Senhor chama o fogo, que consome o vasto abismo e devora a herança do Senhor."},
 {"t":"multipla","p":"Na terceira visão, o que o Senhor tinha na mão?","o":["Uma espada","Um cetro","Um prumo","Uma balança"],"c":2,"v":7,"e":"No versículo 7, o Senhor está sobre um muro erguido a prumo e tem um prumo na mão."},
 {"t":"multipla","p":"Quem era Amazias?","o":["O rei de Judá","Um profeta de Samaria","O sacerdote de Betel","Um filho de Jeroboão"],"c":2,"v":10,"e":"No versículo 10, Amazias é apresentado como o sacerdote de Betel, que manda recado a Jeroboão."},
 {"t":"multipla","p":"Para onde Amazias mandou Amós fugir e profetizar?","o":["Para o Egito","Para a terra de Judá","Para Damasco","Para Samaria"],"c":1,"v":12,"e":"No versículo 12, Amazias diz a Amós que fuja para a terra de Judá e lá coma seu pão e profetize."},
