]}

Amós 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De que terra o Senhor fez subir a família de Israel?","o":["Da Assíria","Do Egito","De Canaã","Da Babilônia"],"c":1,"v":1,"e":"O versículo 1 diz que o Senhor fez Israel subir da terra do Egito."},
 {"t":"multipla","p":"Por ter conhecido somente Israel entre todas as gerações da terra, o que o Senhor diz que fará?","o":["Perdoará todas as suas faltas","Dará a Israel mais terras","Punirá todas as suas iniquidades","Esquecerá as suas transgressões"],"c":2,"v":2,"e":"No versículo 2 o Senhor diz: 'punirei todas as vossas iniquidades sobre vós'."},
 {"t":"multipla","p":"A quem o Senhor revela seu segredo antes de fazer alguma coisa?","o":["Aos seus servos, os profetas","Aos reis de Israel","Aos sacerdotes de Betel","Aos anciãos de Samaria"],"c":0,"v":7,"e":"O versículo 7 diz que o Senhor revela seu segredo a seus servos, os profetas."},
 {"t":"multipla","p":"Onde os castelos de Asdode e do Egito são chamados a se reunir para ver os tumultos e as opressões?","o":["No monte Sião","Nos montes de Samaria","Junto aos altares de Betel","Às margens do Jordão"],"c":1,"v":9,"e":"O versículo 9 manda reunir-se sobre os montes de Samaria para ver os tumultos e as opressões."},
 {"t":"multipla","p":"Na comparação do pastor, o que ele livra da boca do leão?","o":["A ovelha inteira","Um cordeiro vivo","A lã e o couro","As duas patas ou um pedaço da orelha"],"c":3,"v":12,"e":"O versículo 12 diz que o pastor livra da boca do leão as duas patas ou um pedaço da orelha."},
 {"t":"cv","p":"Segundo o capítulo, Israel armazena em seus palácios a justiça e a paz.","c":false,"v":10,"e":"O versículo 10 diz que Israel armazena nos palácios a violência e a devastação, porque não sabe fazer o que é justo."},
